<style scoped lang="scss" src="./gms-configure-report-modal.scss"></style>

<script>
import cloneDeep from "lodash/cloneDeep";
import isEqual from "lodash/isEqual";
import { Component, Prop, Vue, Watch } from "vue-property-decorator";
import Button from "../../components/button/button";
import Modal from "../../components/modal/modal";
import SearchField from "../../components/search-field/search-field";
import Tab from "../../components/tab/tab";
import Tabs from "../../components/tabs/tabs";
import {
  ButtonMode,
  ButtonSize,
  ButtonState,
} from "../button/button.constants";
import { IconShape } from "../icon/icon.constants";
import Icon from "../icon/icon.vue";
import { ModalWidth } from "../modal/modal.constants";
import { SearchFieldMode } from "../search-field/search-field.constants";
import ToggleSwitch from "../toggle-switch/toggle-switch.vue";
import GmsConfigureReportFiltersTab from "./gms-configure-report-modal-filters-tab/gms-configure-report-modal-filters-tab.vue";
import GmsConfigureReportGeneralTab from "./gms-configure-report-modal-general-tab/gms-configure-report-modal-general-tab.vue";
import { MakeDefaultState } from "./gms-configure-report-modal.constants";
import validateReportFilters from "../../util/validate-reporting-filters"

@Component({
  components: {
    Button,
    Icon,
    GmsConfigureReportGeneralTab,
    GmsConfigureReportFiltersTab,
    Modal,
    SearchField,
    Tab,
    Tabs,
    ToggleSwitch,
  },
})
export default class GmsConfigureReportModal extends Vue {
  @Prop({
    type: String,
  })
  focus;

  @Prop({
    type: Array,
    default: () => [],
  })
  headers;

  @Prop({
    type: Boolean,
    default: false,
  })
  initialRollUp;

  @Prop({
    type: Boolean,
    default: false,
  })
  isDefaultReport;

  @Prop({
    type: Boolean,
    default: false,
  })
  canDelete;

  /**
   * Pre-fills the report title field with the original title
   */
  @Prop({
    type: String,
  })
  initialReportTitle;

  /**
   * Pre-fills the visibility field on the general tab
   */
  @Prop({
    type: String,
  })
  initialVisibility;

  /**
   * Populates the visibility dropdown on the general tab
   */
  @Prop({
    type: Object,
    default: () => ({ placeholder: "", options: [] }),
  })
  visibilityConfig;

  /**
   * Pre-fills the filters tab with the existing filter query
   */
  @Prop({
    type: Array,
    default: () => [],
  })
  initialFilters;

  @Prop({
    type: Object,
    default: () => ({ types: [], config: {} }),
  })
  filterConfig;

  /**
   * This is an error message to display to the user. You can set this in
   * response to the save event for validation purposes.
   */
  @Prop({ type: String }) error;

  ModalWidth = ModalWidth;
  ButtonMode = ButtonMode;
  ButtonSize = ButtonSize;
  ButtonState = ButtonState;
  IconShape = IconShape;
  SearchFieldMode = SearchFieldMode;
  MakeDefaultState = MakeDefaultState;

  searchValue = "";

  dragItemBounds = null;
  dragItem = null;
  emptyIndex = -1;
  dragIndex = -1;

  columns = [];
  rollUp = false;
  showDeleteConfirmation = false;
  showMakeDefaultConfirmation = false;
  isUpdateButtonEnabled = false;

  reportName = "";
  visibility = "";
  filters = [];

  beforeMount() {
    this.rollUp = this.initialRollUp;
    this.reportName = this.initialReportTitle;
    this.visibility = this.initialVisibility;
    this.filters = cloneDeep(this.initialFilters);
    this.columns = cloneDeep(this.headers);
    this.$emit("focusChange", this.focus);
  }

  handleInput(value) {
    /**
     * Emits when the user input something in the searchField
     *
     * @event input
     */
    this.searchValue = value;
    this.$emit("input", value);
  }

  get selectedOptions() {
    if (this.searchValue) {
      return this.columns.filter(
        (header) =>
          header.display &&
          header.name.toLowerCase().indexOf(this.searchValue.toLowerCase()) >= 0
      );
    }

    return this.columns.filter((header) => header.display);
  }

  get unselectedOptions() {
    if (this.searchValue) {
      return this.columns.filter(
        (header) =>
          !header.display &&
          header.name.toLowerCase().indexOf(this.searchValue.toLowerCase()) >= 0
      );
    }

    return this.columns.filter((header) => !header.display);
  }

  get dragItemStyle() {
    if (!this.dragItemBounds) return {};

    return {
      cursor: "grabbing",
      position: "fixed",
      left: `${this.dragItemBounds.left}px`,
      top: `${this.dragItemBounds.top}px`,
      width: `${this.dragItemBounds.width}px`,
      height: `${this.dragItemBounds.height}px`,
    };
  }

  @Watch("reportName")
  onReportNameChanged() {
    this.updateButtonState();
  }

  @Watch("visibility")
  onVisibilityChanged() {
    this.updateButtonState();
  }

  @Watch("filters", { deep: true })
  onFiltersChanged() {
    this.updateButtonState();
  }

  @Watch("columns", { deep: true })
  onColumnsChanged() {
    this.updateButtonState();
  }

  @Watch("rollUp")
  onRollUpChanged() {
    this.updateButtonState();
  }

  /**
   * Enables the 'update' button if changes have been made on any of the tabs
   */
  updateButtonState() {
    // changes the 'forceState' prop on the 'Update' button depending on if changes have been made
    // see Button component for details on forceState prop
    this.isUpdateButtonEnabled = this.isFormModified();
  }

  /**
   * Returns if any of the information in any of the three tabs have been modified
   */
  isFormModified() {
    // convert multiselect values (currently arrays) to sets to make comparison easy
    const normalizeArray = (filter) => {
      const { label } = filter.condition;
      return {
        ...filter,
        filterValue: Array.isArray(filter.filterValue)
          ? new Set(filter.filterValue)
          : filter.filterValue,
        condition: { label },
      };
    };

    const oldValues = {
      reportTitle: this.initialReportTitle,
      visibility: this.initialVisibility,
      filters: this.initialFilters.map(normalizeArray),
      columns: this.headers,
      rollUp: this.initialRollUp,
    };

    const newValues = {
      reportTitle: this.reportName,
      visibility: this.visibility,
      filters: cloneDeep(this.filters).map(normalizeArray),
      columns: this.columns,
      rollUp: this.rollUp,
    };

    return !isEqual(oldValues, newValues);
  }

  validateFilters() {
    const {
      isValid,
      error
    } = validateReportFilters(this.filters)

    if (error) {
      this.error = error;
    }

    return !!isValid;
  }

  /**
   * User want to show columns that are not yet showing in the table by clicking headers in the "Other Available Values" section
   */
  handleSelect(column) {
    column.display = true;
  }

  /**
   * User wants to hide columns showing in the table by clicking headers in the "Selected Values" section
   */
  handleUnselect(column) {
    column.display = false;
  }

  handleDeleteConfirmationToggle() {
    this.showDeleteConfirmation = !this.showDeleteConfirmation;
  }

  handleDelete() {
    /**
     * Emits when the user click the delete button
     *
     * @event delete
     */
    this.showDeleteConfirmation = false;
    this.$emit("delete");
  }

  handleCancel() {
    /** Reset all the data back to the initial data */
    this.reportName = this.initialReportTitle;
    this.visibility = this.initialReportTitle;
    this.filters = cloneDeep(this.initialFilters);
    this.columns = cloneDeep(this.headers);

    this.$emit("close");
  }

  handleApply() {
    /**
     * Emits when the user clicks apply button
     *
     * @event configChange
     */
    if (this.validateFilters()) {
      this.$emit(
        "configChange",
        this.columns,
        this.rollUp,
        this.reportName,
        this.visibility,
        this.filters
      );
    }
  }

  exchangeColumn(from, to) {
    let count = -1,
      u = -1,
      v = -1;

    this.columns.forEach((column, i) => {
      if (column.display) {
        count++;
        if (count === from) u = i;
        if (count === to) v = i;
      }
    });

    if (u > v) {
      const temp = this.columns[u];
      this.columns.splice(u, 1);
      this.columns.splice(v, 0, temp);
    } else if (u < v) {
      const temp = this.columns[u];
      this.columns.splice(v + 1, 0, temp);
      this.columns.splice(u, 1);
    }

    /**
     * Emits when the user exchange two options
     *
     * @event exchange
     */
    this.$emit("exchange", this.columns[v], this.columns[u]);
  }

  handleStartDrag(event, item, index) {
    this.dragItem = item;
    this.emptyIndex = index;
    const box = event.currentTarget.getBoundingClientRect();
    const bound = this.$refs.columnOrder.getBoundingClientRect();

    this.dragItemBounds = {
      left: box.left,
      top: box.top,
      width: box.width,
      height: box.height,
    };

    let currentX = event.clientX;
    let currentY = event.clientY;

    this.dragIndex = Math.min(
      Math.max(Math.floor((this.dragItemBounds.top - bound.top) / 41), 0),
      this.columns.length - 1
    );

    const move = (e) => {
      this.dragItemBounds.left += e.clientX - currentX;
      this.dragItemBounds.top += e.clientY - currentY;
      currentX = e.clientX;
      currentY = e.clientY;

      this.dragIndex = Math.min(
        Math.max(Math.floor((this.dragItemBounds.top - bound.top) / 41), 0),
        this.columns.length - 1
      );

      e.preventDefault();
      e.stopPropagation();
      return false;
    };

    const up = () => {
      document.removeEventListener("mousemove", move);
      document.removeEventListener("mouseup", up);
      this.dragItem = null;
      this.exchangeColumn(this.emptyIndex, this.dragIndex);
      this.emptyIndex = -1;
      this.dragIndex = -1;
      this.dragItemBounds = null;
    };

    document.addEventListener("mousemove", move);
    document.addEventListener("mouseup", up);
  }

  getOffsetClass(index) {
    if (this.emptyIndex !== -1 && this.dragIndex !== -1) {
      if (index == this.dragIndex && this.dragIndex > this.emptyIndex) {
        return "GmsConfigureReportModal__NegativeOffset";
      } else if (index == this.dragIndex && this.dragIndex < this.emptyIndex) {
        return "GmsConfigureReportModal__PositiveOffset";
      }
    }

    return "";
  }

  /**
   * General Tab Change Handlers
   */
  handleReportNameChange(newReportName) {
    this.reportName = newReportName.trim();
  }

  handleVisibilityChange(newVisibility) {
    this.visibility = newVisibility;
  }

  handleMakeDefault(makeDefaultState) {
    switch (makeDefaultState) {
      case MakeDefaultState.NO_CHANGES: {
        this.$emit("makeDefault");
        break;
      }
      case MakeDefaultState.CHANGES: {
        this.showMakeDefaultConfirmation = true;
        break;
      }
      case MakeDefaultState.CONFIRMATION_YES: {
        this.showMakeDefaultConfirmation = false;
        this.$emit("makeDefault");
        break;
      }
      case MakeDefaultState.CONFIRMATION_NO: {
        this.showMakeDefaultConfirmation = false;
        break;
      }
    }
  }

  handleRollUpChange(value) {
    this.rollUp = value;
  }

  /**
   * Filters Tab Change Handlers
   */
  handleFiltersChanged(newFilters) {
    this.filters = newFilters;
    this.$emit("onFiltersChanged", newFilters);
  }

  /**
   * Grouped Column Logic
   */
  getUnselectedColumnGroups() {
    const uniqueGroups = [...new Set(this.columns.map(item => item.group))];
    return uniqueGroups;
  }
}
</script>

<template>
  <div>
    <Modal
      title="Customize Report"
      :width="ModalWidth.LARGE"
      @close="$emit('close')"
    >
      <Tabs>
        <Tab title="General">
          <GmsConfigureReportGeneralTab
            :focus="focus"
            :initialRollUp="rollUp"
            :initialReportTitle="initialReportTitle"
            :initialVisibility="initialVisibility"
            :visibilityConfig="visibilityConfig"
            @rollUpChange="handleRollUpChange"
            @reportNameChange="handleReportNameChange"
            @visibilityChange="handleVisibilityChange"
          />
        </Tab>
        <Tab title="Filters">
          <h3 class="GmsConfigureReportModal__error" v-if="error">{{ error }}</h3>
          <GmsConfigureReportFiltersTab
            :initialFilters="initialFilters"
            :filterConfig="filterConfig"
            @onFiltersChanged="handleFiltersChanged($event)"
          />
        </Tab>
        <Tab title="Columns">
          <div class="GmsConfigureReportModal">
            <div class="GmsConfigureReportModal__ColumnsTabHeader">
              <h4 class="GmsConfigureReportModal__ColumnsTabTitle">
                Select and organize your columns
              </h4>
              <div class="GmsConfigureReportModal__Search">
                <SearchField
                  :mode="SearchFieldMode.GMS_CUSTOMIZE"
                  placeholder="Quick Search"
                  @input="handleInput"
                />
              </div>
            </div>
            <div class="GmsConfigureReportModal__Middle">
              <div class="GmsConfigureReportModal__MiddleContent">
                <div class="GmsConfigureReportModal__MiddleLeft">
                  <div class="GmsConfigureReportModal__Recommends">
                    <div class="GmsConfigureReportModal__SubTitle">
                      Selected Columns
                    </div>
                    <div class="GmsConfigureReportModal__Options">
                      <div
                        class="GmsConfigureReportModal__Option"
                        v-for="(item, index) of selectedOptions"
                        :key="index"
                        @click="handleUnselect(item)"
                      >
                        <div class="GmsConfigureReportModal__Check">
                          <Icon
                            :shape="IconShape.CHECK"
                            :size="12"
                            :color="'#ffffff'"
                          />
                        </div>
                        <div class="GmsConfigureReportModal__OptionLabel">
                          {{ item.name }}
                        </div>
                      </div>
                    </div>
                  </div>
                  <div class="GmsConfigureReportModal__Others">
                    <div class="GmsConfigureReportModal__SubTitle">
                      Other Available Columns
                    </div>
                    <div class="GmsConfigureReportModal__GroupedOptions">
                      <div
                        class="GmsConfigureReportModal__OptionGroup"
                        v-for="(groupName, index) of getUnselectedColumnGroups()"
                        :key="index"
                      >
                        <label
                          class="GmsConfigureReportModal__OptionGroupLabel"
                        >
                          {{ groupName || "General" }}
                        </label>
                        <div
                          class="GmsConfigureReportModal__OptionGroupWrapper"
                        >
                          <div class="GmsConfigureReportModal__Options">
                            <div
                              class="GmsConfigureReportModal__Option GmsConfigureReportModal__Option--Unselected"
                              v-for="(item, index) of unselectedOptions.filter(
                                i => i.group === groupName
                              )"
                              :key="index"
                              @click="handleSelect(item)"
                            >
                              <div
                                class="GmsConfigureReportModal__Uncheck"
                              ></div>
                              <div class="GmsConfigureReportModal__OptionLabel">
                                {{ item.name }}
                              </div>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
                <div class="GmsConfigureReportModal__MiddleRight">
                  <div class="GmsConfigureReportModal__SubHeader">
                    <div class="GmsConfigureReportModal__SubTitle">
                      Column Order
                    </div>
                  </div>
                  <div
                    ref="columnOrder"
                    class="GmsConfigureReportModal__ColumnOrder"
                  >
                    <div
                      v-for="(item, index) of selectedOptions"
                      :key="index"
                      @mousedown="handleStartDrag($event, item, index)"
                    >
                      <div
                        v-if="index !== emptyIndex"
                        :class="[
                          'GmsConfigureReportModal__Column',
                          getOffsetClass(index),
                        ]"
                      >
                        <Icon
                          :shape="IconShape.THREE_STRIPES"
                          :size="12"
                          :color="'#C4C4C4'"
                        />
                        <div class="GmsConfigureReportModal__ColumnLabel">
                          {{ item.name }}
                        </div>
                      </div>
                      <div
                        v-else-if="emptyIndex === dragIndex"
                        class="GmsConfigureReportModal__Empty"
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <div
            class="GmsConfigureReportModal__DragColumn"
            v-if="dragItemBounds && dragItem"
            :style="dragItemStyle"
          >
            <Icon
              :shape="IconShape.THREE_STRIPES"
              :size="12"
              :color="'#C4C4C4'"
            />
            <div class="GmsConfigureReportModal__ColumnLabel">
              {{ dragItem.name }}
            </div>
          </div>
        </Tab>
      </Tabs>

      <template v-slot:modal-footer-left>
        <Button
          v-if="canDelete"
          :size="ButtonSize.SMALL"
          label="Delete Report"
          labelColor="red"
          :mode="ButtonMode.TEXT"
          :icon="IconShape.TRASH"
          :iconSize="16"
          iconColor="red"
          @click="handleDeleteConfirmationToggle"
        />
        <Button
          v-if="!isDefaultReport"
          :size="ButtonSize.SMALL"
          label="Set As Default"
          @click="
            handleMakeDefault(
              isFormModified()
                ? MakeDefaultState.CHANGES
                : MakeDefaultState.NO_CHANGES
            )
          "
          :mode="ButtonMode.SUBTLE"
          :forceState="isDefaultReport ? ButtonState.DISABLE : undefined"
        />
        <div v-else class="GmsConfigureReportModal__DefaultReport">
          <Icon :shape="IconShape.STAR_FULL" :size="14.25" :color="'#2fc8a3'" />
          <p class="GmsConfigureReportModal__DefaultReportText">
            This is your default report.
          </p>
        </div>
      </template>

      <template v-slot:modal-footer-right>
        <Button
          :size="ButtonSize.SMALL"
          label="Apply"
          labelColor="white"
          @click="handleApply"
          :mode="ButtonMode.PRIMARY"
          :forceState="isUpdateButtonEnabled ? undefined : ButtonState.DISABLE"
        />
        <Button
          :size="ButtonSize.SMALL"
          label="Cancel"
          @click="handleCancel"
          :mode="ButtonMode.SUBTLE"
        />
      </template>
    </Modal>

    <!-- Delete Report Confirmation Modal -->
    <Modal
      v-if="showDeleteConfirmation"
      @close="showDeleteConfirmation = false"
      title="Delete Report"
    >
      <p class="GmsConfigureReportModal__ConfirmationText">
        Are you sure you want to delete this report?
      </p>
      <template v-slot:modal-footer-right>
        <Button
          :size="ButtonSize.SMALL"
          label="Delete Report"
          backgroundColor="red"
          labelColor="white"
          :mode="ButtonMode.PRIMARY"
          :icon="IconShape.TRASH"
          iconColor="white"
          :iconSize="16"
          @click="handleDelete"
        />
        <Button
          :size="ButtonSize.SMALL"
          label="Cancel"
          @click="handleDeleteConfirmationToggle"
          :mode="ButtonMode.SUBTLE"
        />
      </template>
    </Modal>

    <!-- Make Default Confirmation Modal -->
    <Modal
      v-if="showMakeDefaultConfirmation"
      @close="showMakeDefaultConfirmation = false"
    >
      <p class="GmsConfigureReportModal__ConfirmationText">
        Your changes will be lost if you don't apply them before making this the
        default report. Is that ok?
      </p>
      <template v-slot:modal-footer-right>
        <Button
          :size="ButtonSize.SMALL"
          label="Yes"
          backgroundColor="red"
          labelColor="white"
          :mode="ButtonMode.PRIMARY"
          @click="handleMakeDefault(MakeDefaultState.CONFIRMATION_YES)"
        />
        <Button
          :size="ButtonSize.SMALL"
          label="Cancel"
          @click="handleMakeDefault(MakeDefaultState.CONFIRMATION_NO)"
          :mode="ButtonMode.SUBTLE"
        />
      </template>
    </Modal>
  </div>
</template>
